"""Nucleo de Machine Learning (aprendizado supervisionado) em Python puro.

Implementa, sem bibliotecas externas:
  - pre-processamento (one-hot + padronizacao)
  - regressao logistica (classificacao binaria) via gradiente descendente
  - arvore de decisao (classificacao) como modelo de comparacao
  - regressao linear (previsao de dias de atraso)
  - metricas, validacao cruzada, importancia de variaveis
  - persistencia do modelo em JSON
"""

import csv
import json
import math
import os
import random

SEMENTE = 42


# ---------------------------------------------------------------- leitura
def ler_csv(caminho):
    with open(caminho, "r", encoding="utf-8-sig", newline="") as f:
        leitor = csv.DictReader(f)
        linhas = [dict(l) for l in leitor]
    return linhas


def para_numero(v):
    if v is None:
        return None
    t = str(v).strip()
    if t == "":
        return None
    try:
        return float(t)
    except ValueError:
        return None


# ------------------------------------------------------ pre-processador
class Preprocessador:
    """Ajusta encoder one-hot e padronizacao apenas no treino (sem vazamento)."""

    def __init__(self):
        self.numericas = []
        self.categoricas = []
        self.cat_valores = {}   # col -> lista ordenada de categorias
        self.means = {}
        self.stds = {}
        self.colunas_saida = []  # nomes finais das features
        self._ajustado = False

    def ajustar(self, linhas, numericas, categoricas):
        self.numericas = list(numericas)
        self.categoricas = list(categoricas)
        # categorias ordenadas
        for c in categoricas:
            vals = sorted({l[c] for l in linhas})
            self.cat_valores[c] = vals
        # estatisticas das numericas
        for c in numericas:
            vals = [para_numero(l[c]) for l in linhas]
            vals = [v for v in vals if v is not None]
            m = sum(vals) / len(vals)
            var = sum((v - m) ** 2 for v in vals) / len(vals)
            self.means[c] = m
            self.stds[c] = math.sqrt(var) if var > 0 else 1.0
        # monta lista de colunas de saida
        self.colunas_saida = []
        for c in numericas:
            self.colunas_saida.append(c)
        for c in categoricas:
            for v in self.cat_valores[c]:
                self.colunas_saida.append("%s=%s" % (c, v))
        self._ajustado = True

    def transformar_linha(self, linha):
        if not self._ajustado:
            raise RuntimeError("Preprocessador nao ajustado.")
        out = []
        for c in self.numericas:
            v = para_numero(linha[c])
            if v is None:
                v = self.means[c]
            out.append((v - self.means[c]) / self.stds[c])
        for c in self.categoricas:
            val = linha[c]
            for v in self.cat_valores[c]:
                out.append(1.0 if val == v else 0.0)
        return out

    def transformar(self, linhas):
        return [self.transformar_linha(l) for l in linhas]

    def para_dict(self):
        return {
            "numericas": self.numericas,
            "categoricas": self.categoricas,
            "cat_valores": self.cat_valores,
            "means": self.means,
            "stds": self.stds,
            "colunas_saida": self.colunas_saida,
        }

    @staticmethod
    def de_dict(d):
        p = Preprocessador()
        p.numericas = d["numericas"]
        p.categoricas = d["categoricas"]
        p.cat_valores = d["cat_valores"]
        p.means = d["means"]
        p.stds = d["stds"]
        p.colunas_saida = d["colunas_saida"]
        p._ajustado = True
        return p


# -------------------------------------------------- regressao logistica
def sigmoid(x):
    if x >= 0:
        z = math.exp(-x)
        return 1.0 / (1.0 + z)
    z = math.exp(x)
    return z / (1.0 + z)


class RegressaoLogistica:
    def __init__(self, taxa=0.05, epocas=2000, l2=0.01, semente=SEMENTE):
        self.taxa = taxa
        self.epocas = epocas
        self.l2 = l2
        self.semente = semente
        self.pesos = None
        self.historico = []

    def ajustar(self, X, y):
        rng = random.Random(self.semente)
        n = len(X)
        p = len(X[0])
        self.pesos = [rng.uniform(-0.01, 0.01) for _ in range(p + 1)]  # +bias
        for ep in range(self.epocas):
            grad = [0.0] * (p + 1)
            perda = 0.0
            for i in range(n):
                xi = [1.0] + list(X[i])
                yi = y[i]
                z = sum(self.pesos[j] * xi[j] for j in range(p + 1))
                pred = sigmoid(z)
                erro = pred - yi
                for j in range(p + 1):
                    grad[j] += erro * xi[j]
                # log loss
                eps = 1e-12
                perda += -(yi * math.log(pred + eps) + (1 - yi) * math.log(1 - pred + eps))
            for j in range(p + 1):
                reg = 0.0 if j == 0 else self.l2 * self.pesos[j]
                self.pesos[j] -= self.taxa * (grad[j] / n + reg)
            self.historico.append(perda / n)
        return self

    def probabilidade(self, x):
        xi = [1.0] + list(x)
        z = sum(self.pesos[j] * xi[j] for j in range(len(self.pesos)))
        return sigmoid(z)

    def prever(self, X, limiar=0.5):
        return [1 if self.probabilidade(x) >= limiar else 0 for x in X]

    def para_dict(self):
        return {"taxa": self.taxa, "epocas": self.epocas, "l2": self.l2,
                "pesos": self.pesos, "historico": self.historico[-5:]}

    @staticmethod
    def de_dict(d):
        m = RegressaoLogistica(taxa=d["taxa"], epocas=d["epocas"], l2=d["l2"])
        m.pesos = d["pesos"]
        m.historico = d.get("historico", [])
        return m


# -------------------------------------------------- arvore de decisao
class NoArvore:
    def __init__(self, predicao=None, feature=None, limiar=None, esq=None, dir_=None):
        self.predicao = predicao
        self.feature = feature
        self.limiar = limiar
        self.esq = esq
        self.dir = dir_


class ArvoreDecisao:
    def __init__(self, max_prof=5, min_amostras=12, semente=SEMENTE):
        self.max_prof = max_prof
        self.min_amostras = min_amostras
        self.semente = semente
        self.raiz = None
        self.importancias = None

    def _gini(self, y):
        if not y:
            return 0.0
        n = len(y)
        p1 = sum(y) / n
        return 1.0 - p1 * p1 - (1 - p1) * (1 - p1)

    def _melhor_split(self, X, y):
        n = len(y)
        p = len(X[0])
        melhor = None
        melhor_ganho = 0.0
        gini_pai = self._gini(y)
        for feat in range(p):
            valores = sorted({X[i][feat] for i in range(n)})
            # candidatos de limiar: pontos medios
            for t in range(len(valores) - 1):
                limiar = (valores[t] + valores[t + 1]) / 2.0
                esq_y, dir_y = [], []
                esq_idx, dir_idx = [], []
                for i in range(n):
                    if X[i][feat] <= limiar:
                        esq_y.append(y[i]); esq_idx.append(i)
                    else:
                        dir_y.append(y[i]); dir_idx.append(i)
                if len(esq_y) < self.min_amostras or len(dir_y) < self.min_amostras:
                    continue
                gini_filho = (len(esq_y) / n) * self._gini(esq_y) + (len(dir_y) / n) * self._gini(dir_y)
                ganho = gini_pai - gini_filho
                if ganho > melhor_ganho + 1e-12:
                    melhor_ganho = ganho
                    melhor = (feat, limiar, esq_idx, dir_idx)
        return melhor, melhor_ganho

    def _construir(self, X, y, prof):
        # predicao majoritaria
        if not y:
            return NoArvore(predicao=0)
        if prof >= self.max_prof or len(set(y)) == 1 or len(y) < 2 * self.min_amostras:
            pred = 1 if (sum(y) / len(y) >= 0.5) else 0
            return NoArvore(predicao=pred)
        res, ganho = self._melhor_split(X, y)
        if res is None or ganho <= 1e-9:
            pred = 1 if (sum(y) / len(y) >= 0.5) else 0
            return NoArvore(predicao=pred)
        feat, limiar, esq_idx, dir_idx = res
        Xe = [X[i] for i in esq_idx]; ye = [y[i] for i in esq_idx]
        Xd = [X[i] for i in dir_idx]; yd = [y[i] for i in dir_idx]
        no = NoArvore(feature=feat, limiar=limiar)
        no.esq = self._construir(Xe, ye, prof + 1)
        no.dir = self._construir(Xd, yd, prof + 1)
        return no

    def ajustar(self, X, y, nomes_features=None):
        self.nomes = nomes_features
        self.raiz = self._construir(X, y, 0)
        return self

    def _prever_um(self, x, no):
        if no.predicao is not None and no.feature is None:
            return no.predicao
        if no.feature is None:
            return no.predicao
        if x[no.feature] <= no.limiar:
            return self._prever_um(x, no.esq)
        return self._prever_um(x, no.dir)

    def prever(self, X):
        return [self._prever_um(x, self.raiz) for x in X]


# -------------------------------------------------- regressao linear
class RegressaoLinear:
    def __init__(self, taxa=0.01, epocas=3000, l2=0.0, semente=SEMENTE):
        self.taxa = taxa
        self.epocas = epocas
        self.l2 = l2
        self.semente = semente
        self.pesos = None

    def ajustar(self, X, y):
        rng = random.Random(self.semente)
        n = len(X); p = len(X[0])
        self.pesos = [rng.uniform(-0.01, 0.01) for _ in range(p + 1)]
        for _ in range(self.epocas):
            grad = [0.0] * (p + 1)
            for i in range(n):
                xi = [1.0] + list(X[i])
                pred = sum(self.pesos[j] * xi[j] for j in range(p + 1))
                erro = pred - y[i]
                for j in range(p + 1):
                    grad[j] += erro * xi[j]
            for j in range(p + 1):
                reg = 0.0 if j == 0 else self.l2 * self.pesos[j]
                self.pesos[j] -= self.taxa * (grad[j] / n + reg)
        return self

    def prever(self, X):
        out = []
        for x in X:
            xi = [1.0] + list(x)
            out.append(sum(self.pesos[j] * xi[j] for j in range(len(self.pesos))))
        return out


# ----------------------------------------------------------- metricas
def matriz_confusao(y_real, y_pred):
    tp = sum(1 for r, p in zip(y_real, y_pred) if r == 1 and p == 1)
    tn = sum(1 for r, p in zip(y_real, y_pred) if r == 0 and p == 0)
    fp = sum(1 for r, p in zip(y_real, y_pred) if r == 0 and p == 1)
    fn = sum(1 for r, p in zip(y_real, y_pred) if r == 1 and p == 0)
    return {"VP": tp, "VN": tn, "FP": fp, "FN": fn}


def metricas_classificacao(y_real, y_pred):
    mc = matriz_confusao(y_real, y_pred)
    tp, tn, fp, fn = mc["VP"], mc["VN"], mc["FP"], mc["FN"]
    acc = (tp + tn) / len(y_real) if y_real else 0.0
    prec = tp / (tp + fp) if (tp + fp) > 0 else 0.0
    rec = tp / (tp + fn) if (tp + fn) > 0 else 0.0
    f1 = 2 * prec * rec / (prec + rec) if (prec + rec) > 0 else 0.0
    return {"acuracia": acc, "precisao": prec, "recall": rec, "f1": f1,
            "matriz": mc}


def rmse(y_real, y_pred):
    n = len(y_real)
    return math.sqrt(sum((r - p) ** 2 for r, p in zip(y_real, y_pred)) / n)


def mae(y_real, y_pred):
    n = len(y_real)
    return sum(abs(r - p) for r, p in zip(y_real, y_pred)) / n


# -------------------------------------------------- validacao cruzada
def k_fold_indices(n, k=5, semente=SEMENTE):
    idx = list(range(n))
    rng = random.Random(semente)
    rng.shuffle(idx)
    folds = [[] for _ in range(k)]
    for i, v in enumerate(idx):
        folds[i % k].append(v)
    return folds


def validacao_cruzada_logistica(X, y, k=5, taxa=0.05, epocas=800, l2=0.01):
    folds = k_fold_indices(len(X), k)
    resultados = []
    for i in range(k):
        teste_idx = set(folds[i])
        Xtr = [X[j] for j in range(len(X)) if j not in teste_idx]
        ytr = [y[j] for j in range(len(y)) if j not in teste_idx]
        Xte = [X[j] for j in range(len(X)) if j in teste_idx]
        yte = [y[j] for j in range(len(y)) if j in teste_idx]
        m = RegressaoLogistica(taxa=taxa, epocas=epocas, l2=l2, semente=SEMENTE + i)
        m.ajustar(Xtr, ytr)
        pred = m.prever(Xte)
        met = metricas_classificacao(yte, pred)
        resultados.append(met)
    # media
    chaves = ["acuracia", "precisao", "recall", "f1"]
    media = {c: sum(r[c] for r in resultados) / len(resultados) for c in chaves}
    return media, resultados


# --------------------------------------------------------- importancia
def importancia_logistica(modelo, nomes):
    # coeficientes padronizados (ja em escala padronizada) -> magnitude
    coefs = modelo.pesos[1:]
    pares = sorted(zip(nomes, coefs), key=lambda t: abs(t[1]), reverse=True)
    return pares


# ----------------------------------------------------------- persistencia
def salvar_modelo(caminho, preproc, modelo_log, modelo_tree, modelo_lin,
                  metadata):
    obj = {
        "preproc": preproc.para_dict(),
        "logistica": modelo_log.para_dict(),
        "arvore": None,  # arvore nao serializada (estrutura); re-treina se preciso
        "linear": {"pesos": modelo_lin.pesos, "taxa": modelo_lin.taxa,
                   "epocas": modelo_lin.epocas},
        "metadata": metadata,
    }
    # serializa arvore manualmente
    def serializar_no(no):
        if no is None:
            return None
        if no.feature is None:
            return {"tipo": "folha", "predicao": no.predicao}
        return {"tipo": "split", "feature": no.feature, "limiar": no.limiar,
                "esq": serializar_no(no.esq), "dir": serializar_no(no.dir)}
    obj["arvore"] = serializar_no(modelo_tree.raiz)
    obj["arvore_params"] = {"max_prof": modelo_tree.max_prof,
                            "min_amostras": modelo_tree.min_amostras}
    with open(caminho, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=2)


def carregar_modelo(caminho):
    with open(caminho, "r", encoding="utf-8") as f:
        obj = json.load(f)
    preproc = Preprocessador.de_dict(obj["preproc"])
    log = RegressaoLogistica.de_dict(obj["logistica"])
    lin = RegressaoLinear(taxa=obj["linear"]["taxa"], epocas=obj["linear"]["epocas"])
    lin.pesos = obj["linear"]["pesos"]
    # arvore
    def desserializar_no(d):
        if d is None:
            return None
        if d["tipo"] == "folha":
            return NoArvore(predicao=d["predicao"])
        no = NoArvore(feature=d["feature"], limiar=d["limiar"])
        no.esq = desserializar_no(d["esq"])
        no.dir = desserializar_no(d["dir"])
        return no
    tree = ArvoreDecisao(max_prof=obj["arvore_params"]["max_prof"],
                         min_amostras=obj["arvore_params"]["min_amostras"])
    tree.raiz = desserializar_no(obj["arvore"])
    tree.nomes = preproc.colunas_saida
    return preproc, log, tree, lin, obj["metadata"]

